"""Write docs/lanes/LDL-assets-shortfall.md: per species, best free asset grade, what is missing, downloadable-but-ungraded
Sketchfab candidates, and which paid Xfrog library (species list read from xfrog.com product pages, 2026-11-22) covers it."""
import json
from pathlib import Path
R = Path(__file__).resolve().parents[1]
P = R / "knowledge/landscape/plants"
assets = {a["id"]: a for a in json.loads((P / "assets.json").read_text())["assets"]}
rows = json.loads((P / "assets.json").read_text())["species"]
cand = json.loads((P / "sketchfab-candidates.json").read_text())
# species -> Xfrog library (product-page species lists). Genus-level or different species are marked.
XF = {
 "cupressus_sempervirens": "Mediterranean", "laurus_nobilis": "Mediterranean", "nerium_oleander": "Mediterranean (also Blossoming; a free Oleander sample is on xfrog.com)",
 "olea_europaea": "Mediterranean (Bonsai library has a bonsai olive)", "phoenix_dactylifera": "Fruit Trees", "ficus_carica": "Fruit Trees (Shrubs library too)",
 "punica_granatum": "Fruit Trees", "citrus_x_sinensis": "Fruit Trees / Tropical Trees", "citrus_limon": "Fruit Trees", "eriobotrya_japonica": "Fruit Trees",
 "psidium_guajava": "Fruit Trees (guava)", "lagerstroemia_indica": "Blossoming", "murraya_paniculata": "Oceania 2", "pittosporum_tobira": "HD Plants 2",
 "nelumbo_nucifera": "Flowers 3 (Nelumbo sp.)", "zantedeschia_aethiopica": "Flowers 3 (Zantedeschia sp.)", "hibiscus_rosa_sinensis": "Landscaping / Flowers 3 (Hibiscus, species not stated)",
 "vitis_vinifera": "Agriculture (check list)", "strelitzia_reginae": "Flowers 1 (check list)",
}
L = ["# LDL pass 2: free-asset shortfall and paid options", "",
     "Generated by `scripts/ldl_shortfall.py` from `knowledge/landscape/plants/assets.json`, `sketchfab-candidates.json` and the Xfrog species lists.", "",
     "## Free shortfall (species -> best free asset grade -> what is missing)", "",
     "| species | drawable | best free asset (grade, fit) | what is missing | free Sketchfab candidates (ungraded, token needed) | paid cover |", "|---|---|---|---|---|---|"]
for r in rows:
    s = r["slug"]; a = assets.get(r.get("best_asset") or "")
    best = f"{a['id']} ({a['grade']}, {a['species_fit']})" if a else "none"
    if r["drawable"] == "drawable":
        miss = "nothing for a still; " + ("drift use only, patches 6 m+" if s == "gazania_rigens" else "genus-level" if a["species_fit"] == "genus" else "ok")
    elif r["drawable"] == "drawable_as_genus_standin":
        miss = "right species (fruit colour wrong on stand-in)"
    elif a:
        miss = f"asset fails grade ({a['grade']}): {a['rationale'][11:90].rstrip()}..."
    else:
        miss = "no free asset of this species or genus on this machine"
    c = cand.get(s, [])
    cs = f"{len(c)} ({sum(h['match']=='species' for h in c)} species-named)" if c else "0"
    L.append(f"| {s} | {r['drawable']} | {best} | {miss} | {cs} | {XF.get(s, '')} |")
L += ["", "## Paid options (NOT bought; for the lead to put to the client)", "",
 "Prices read from vendor pages on 2026-11-22; they change. Licences are the vendor's, not read in full: check the licence text before purchase (use in client renders, Blender Cycles, no AI-training clause).", "",
 "| product | vendor | licence / formats | price | covers (missing palette species) |", "|---|---|---|---|---|",
 "| XfrogPlants Library: Mediterranean (20 species x 3 ages) | Xfrog (xfrog.com; also TurboSquid, CGTrader) | Royalty free; FBX/OBJ/Blender/Alembic etc. per vendor page | $99 list, $79 sale | Cupressus sempervirens, Laurus nobilis, Nerium oleander, Olea europaea |",
 "| XfrogPlants Library: Fruit Trees | Xfrog | as above | $99 list, $79 sale | Phoenix dactylifera, Ficus carica, Punica granatum, Citrus x sinensis (fruit colour right), Citrus limon, Eriobotrya japonica, Psidium; dropped species Mangifera indica, Musa |",
 "| XfrogPlants Library: Tropical Trees | Xfrog | as above | $99 list, $79 sale | Musa, Mangifera, Citrus sinensis, Phoenix canariensis (not dactylifera), Cocos, Syagrus, Chamaerops |",
 "| XfrogPlants Library: Blossoming | Xfrog | as above | $99 list, $79 sale | Lagerstroemia indica, Nerium oleander (also Magnolia, Prunus) |",
 "| XfrogPlants Library: Flowers 3 | Xfrog | as above | $99 list, $79 sale | Nelumbo, Zantedeschia, Hibiscus (genus level; species not stated on the page) |",
 "| XfrogPlants Library: Oceania 2 / HD Plants 2 | Xfrog | as above | $99 / $79 each | Murraya paniculata (Oceania 2); Pittosporum tobira (HD Plants 2) |",
 "| Xfrog World bundle (31 libraries) | Xfrog | as above | $500 list, $499 sale | all of the above in one purchase; none of Japan/Asia lists carries Fatsia, Nandina, Acorus, Rhapis (checked) |",
 "| Laubwerk Plants Kits | Laubwerk (laubwerk.com via Toolfarm) | per-kit licence; player plug-ins for 3ds Max, Maya, C4D, SketchUp and Python; Blender support NOT confirmed | roughly $69 sale to $159 MSRP per kit (2024-26 listings) | unverified: Kit 7 is 10 tropical palms (species list not read); free Plants Kit freebie includes frangipani |",
 "| Botaniq (trees, plants, grass) | Polygoniq (Superhive / Blender Market) | Blender-native add-on, royalty-free per vendor | $99.99 full library; $39.99 for 42%; $1.99 starter | species coverage NOT verified (geographic filter by world map); candidate for generic Mediterranean/subtropical fill-in |", "",
 "Not covered by any option found: Fatsia japonica, Nandina domestica, Acorus gramineus, Farfugium japonicum, Rhapis excelsa, Bambusa multiplex, Ophiopogon, Liriope, Alpinia zerumbet, Plumbago, Petrea, Podranea, Pentas, Justicia, Jasminum sambac/grandiflorum, Thaumatophyllum, Strelitzia nicolai, Cyperus papyrus/involucratus, Iris laevigata, Pontederia, Nymphaea caerulea. For these: Sketchfab candidates (free, once a token exists) or commissioned modelling.", ""]
(R / "docs/lanes/LDL-assets-shortfall.md").write_text("\n".join(L) + "\n")
print(len(rows))
